def main():
    os.environ["LUMINA_EDITORIAL"] = str(Path(__file__).resolve().with_name("editorial.json"))
    runtime=Path(tempfile.mkdtemp(prefix='lumina-3-0-'))
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(_PAYLOAD))) as archive:
        archive.extractall(runtime)
    sys.path.insert(0,str(runtime))
    os.chdir(runtime)
    if '--self-test' in sys.argv:
        import unittest
        suite=unittest.defaultTestLoader.discover(str(runtime/'tests'))
        result=unittest.TextTestRunner(verbosity=2).run(suite)
        sys.exit(0 if result.wasSuccessful() else 1)
    import uvicorn
    uvicorn.run('app:app',host='0.0.0.0',port=int(os.environ.get('PORT','8000')),log_level='info')
if __name__=='__main__':main()
